put('sections/contact.liquid',section('Contact','''<section class="wrap section-space contact-grid"><div><h1>{{ 'contact.title' | t }}</h1><p class="lede">{{ 'contact.intro' | t }}</p>{% if settings.support_email != blank %}<a class="text-link" href="mailto:{{ settings.support_email | escape }}">{{ settings.support_email | escape }}</a>{% endif %}{% if settings.support_hours != blank %}<p>{{ settings.support_hours | escape }}</p>{% endif %}</div>{% form 'contact', class: 'contact-form' %}{{ form.errors | default_errors }}{% if form.posted_successfully? %}<p role="status">{{ 'general.sent' | t }}</p>{% endif %}<label for="ContactName">{{ 'general.name' | t }}</label><input id="ContactName" name="contact[name]" autocomplete="name" value="{{ form.name | escape }}"><label for="ContactEmail">{{ 'general.email' | t }}</label><input id="ContactEmail" name="contact[email]" type="email" required autocomplete="email" value="{{ form.email | escape }}"><label for="ContactBody">{{ 'general.message' | t }}</label><textarea id="ContactBody" name="contact[body]" rows="6" required>{{ form.body | escape }}</textarea><button class="button">{{ 'general.send' | t }}</button>{% endform %}</section>'''))
put('sections/main-search.liquid',section('Search','''<section class="wrap section-space"><h1>{{ 'general.search' | t }}</h1><form action="{{ routes.search_url }}" method="get" role="search" class="search-form"><label for="SearchInput">{{ 'general.search_label' | t }}</label><div class="inline-form"><input id="SearchInput" type="search" name="q" value="{{ search.terms | escape }}" required><button class="button">{{ 'general.search' | t }}</button></div></form>{% if search.performed %}{% paginate search.results by 12 %}<div class="product-grid">{% for item in search.results %}{% if item.object_type == 'product' %}{% render 'product-card', item: item %}{% else %}<article><h2><a href="{{ item.url }}">{{ item.title | escape }}</a></h2></article>{% endif %}{% else %}<p>{{ 'general.search_empty' | t }}</p>{% endfor %}</div>{{ paginate | default_pagination }}{% endpaginate %}{% endif %}</section>''',presets=False))
put('snippets/cart-content.liquid','''{% doc %}
Renders the server-side cart form for both cart page and drawer.
{% enddoc %}
{% if cart.empty? %}<div class="empty-cart"><p>{{ 'general.empty' | t }}</p><a class="button" href="{{ routes.all_products_collection_url }}">{{ 'general.continue' | t }}</a></div>{% else %}<form action="{{ routes.cart_url }}" method="post" class="cart-form"><div class="cart-items">{% for item in cart.items %}<div class="cart-item">{% if item.image %}{{ item.image | image_url: width: 240 | image_tag: loading: 'lazy' }}{% endif %}<div><a href="{{ item.url }}"><strong>{{ item.product.title | escape }}</strong></a>{% unless item.product.has_only_default_variant %}<p>{{ item.variant.title | escape }}</p>{% endunless %}<div>{{ item.final_line_price | money }}</div><label for="CartQty-{{ forloop.index }}">{{ 'general.quantity' | t }}</label><input id="CartQty-{{ forloop.index }}" name="updates[]" type="number" min="0" step="1" value="{{ item.quantity }}" data-line="{{ forloop.index }}"><a href="{{ item.url_to_remove }}">{{ 'general.remove' | t }}</a></div></div>{% endfor %}</div><div class="cart-total"><span>{{ 'cart.subtotal' | t }}</span><strong>{{ cart.total_price | money }}</strong></div>{% for discount in cart.cart_level_discount_applications %}<p>{{ discount.title | escape }} −{{ discount.total_allocated_amount | money }}</p>{% endfor %}<p>{{ 'general.shipping_note' | t }}</p><button class="button secondary" name="update">{{ 'general.update' | t }}</button><button class="button" name="checkout">{{ 'general.checkout' | t }}</button></form>{% endif %}''')
put('sections/main-cart.liquid',section('Cart','''<section class="wrap section-space narrow"><h1>{{ 'cart.title' | t }}</h1>{% render 'cart-content' %}</section>''',presets=False))
put('sections/cart-drawer-content.liquid',section('Cart drawer content',"{% render 'cart-content' %}",presets=False))
put('sections/main-404.liquid',section('Not found','''<section class="wrap section-space narrow"><p>404</p><h1>{{ 'general.not_found' | t }}</h1><p>{{ 'general.not_found_text' | t }}</p><a class="button" href="{{ routes.root_url }}">{{ 'general.home' | t }}</a></section>''',presets=False))
put('sections/password.liquid',section('Password','''<section class="password-page wrap"><span class="wordmark">{{ settings.brand | escape }}</span><h1>{{ 'general.password_intro' | t }}</h1><div class="rte">{{ shop.password_message }}</div>{% form 'storefront_password' %}{{ form.errors | default_errors }}<label for="StorePassword">{{ 'general.password' | t }}</label><input id="StorePassword" type="password" name="password" required autocomplete="current-password"><button class="button">{{ 'general.enter' | t }}</button>{% endform %}</section>''',presets=False))
