details={'blocks':{'d1':{'type':'detail','settings':{'title':'Two separate openings','text':'<p>One continuous housing, with a channel for each knee.</p>'}},'d2':{'type':'detail','settings':{'title':'360 × 242 × 160 mm','text':'<p>Overall device dimensions.</p>'}},'d3':{'type':'detail','settings':{'title':'A clear central control panel','text':'<p>A blue-lit display on the top of the housing.</p>'}}},'block_order':['d1','d2','d3']}
